-- GROUP 09: LRT STATION PASSENGER FLOW AND TRAIN OPERATIONS
-- Database: G09_lrtops. Target assumption: MySQL 8.0.16+ / InnoDB.
-- Version 4.0 hand-off: no CHECK clauses and no standalone KEY/INDEX declarations.
-- PRIMARY KEY / FOREIGN KEY / UNIQUE, ENUM, NOT NULL and defaults retained.
-- No lookup/subtype tables, triggers, stored routines, or index workarounds.
--
-- COMPLETE DATA YEAR: 2025-01-01 to 2025-12-31; current snapshot at year end.
-- All stations, addresses, assets, specifications, capacities, service events,
-- passenger volumes and restrictions are simulated. Names may coincide with real
-- places but do not assert real geography, operator records or actual events.
-- Capacity numbers are illustrative register values, NOT verified safety limits.
-- This is NOT the actual operation, timetable or ridership of an LRT operator.
-- No passenger identities, ticket records, boarding/alighting or observations.
-- No occupancy, capacity-breach, punctuality or train-load calculation is implied.
--
-- The bounded dataset has four operating stations and one inactive station under
-- commissioning. Each retains one Northbound and one Southbound platform.
-- Twelve passenger consists circulate; two reserve registrations have no calls.
-- Service trains include an inspection consist with occasional pre-intake calls
-- and other Service consists with tasks but no station calls.
-- Every call keeps its arrival and departure on the same directional platform.
-- Terminal repositioning, depot movements and detailed reversal operations are
-- outside the recorded visit model; no call is repointed across platforms.
-- Day-start distribution assumes overnight positioning outside the monitored
-- visit window. Same-day consists are reused only after arrival/departure and
-- a turnaround allowance. The end-of-year final visit remains Arrived.
--
-- Counts are consolidated 15-minute station totals, not platform counts or gate
-- device events. Nominal counting window: 05:30 through 22:00, 66 intervals/day.
-- Missing intervals are absent, never filled with fabricated zeros. Counter
-- interruptions sometimes use Manual counts. A simulated planned suspension on
-- 18 April has completed zero counts; it is NOT a claim about real LRT service.
-- Peaks, weekends, station roles, daily factors and local variation shape counts.
-- Gate counts are generated independently of train visits; no passenger journey
-- or station/platform occupancy is inferred from entries minus exits.
-- Similar arrival totals across operating stations are expected: passenger trips
-- stop at each registered corridor station, not invented skipped-stop services.
--
-- Fresh creation only; not a migration. No DROP commands. Stop on the first
-- error; never use --force. Existing tables will cause errors. MySQL DDL is not
-- transactional; all seed INSERTs form one transaction. No character set declared.
-- Data volume reflects a full operating year rather than a few sample days.

SET SESSION sql_mode = 'STRICT_TRANS_TABLES,ONLY_FULL_GROUP_BY,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
CREATE DATABASE IF NOT EXISTS G09_lrtops_old;
USE G09_lrtops_old;

CREATE TABLE `station` (
 `stncode` VARCHAR(8) NOT NULL PRIMARY KEY,
 `stnname` VARCHAR(100) NOT NULL,
 `brgycode` VARCHAR(8) NOT NULL,
 `brgyname` VARCHAR(80) NOT NULL,
 `address` VARCHAR(180) NOT NULL,
 `active` TINYINT UNSIGNED NOT NULL DEFAULT 0,
 `revno` INT UNSIGNED NOT NULL DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE `platform` (
 `platno` VARCHAR(12) NOT NULL PRIMARY KEY,
 `stncode` VARCHAR(8) NOT NULL,
 `platname` VARCHAR(80) NOT NULL,
 `directn` ENUM('Northbound','Southbound') NOT NULL,
 `capacity` INT UNSIGNED NOT NULL,
 `active` TINYINT UNSIGNED NOT NULL DEFAULT 1,
 `revno` INT UNSIGNED NOT NULL DEFAULT 1,
 CONSTRAINT uq_station_direction UNIQUE (`stncode`,`directn`),
 CONSTRAINT uq_station_platform_name UNIQUE (`stncode`,`platname`),
 FOREIGN KEY (`stncode`) REFERENCES `station`(`stncode`)
   ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE `train` (
 `trainno` VARCHAR(12) NOT NULL PRIMARY KEY,
 `label` VARCHAR(80) NOT NULL,
 `traintyp` ENUM('Passenger','Service') NOT NULL,
 `cars` SMALLINT UNSIGNED NULL,
 `paxcap` INT UNSIGNED NULL,
 `dutytype` ENUM('Inspection','Maintenance','Recovery') NULL,
 `loadton` DECIMAL(8,2) NULL,
 `active` TINYINT UNSIGNED NOT NULL DEFAULT 1,
 `revno` INT UNSIGNED NOT NULL DEFAULT 1
) ENGINE=InnoDB;

CREATE TABLE `traincall` (
 `callno` VARCHAR(16) NOT NULL PRIMARY KEY,
 `trainno` VARCHAR(12) NOT NULL,
 `platno` VARCHAR(12) NOT NULL,
 `arrat` DATETIME NOT NULL,
 `depat` DATETIME NULL,
 `status` ENUM('Arrived','Departed') NOT NULL DEFAULT 'Arrived',
 `remarks` VARCHAR(255) NULL,
 `revno` INT UNSIGNED NOT NULL DEFAULT 1,
 FOREIGN KEY (`trainno`) REFERENCES `train`(`trainno`)
   ON DELETE RESTRICT ON UPDATE RESTRICT,
 FOREIGN KEY (`platno`) REFERENCES `platform`(`platno`)
   ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE `gateflow` (
 `stncode` VARCHAR(8) NOT NULL,
 `startat` DATETIME NOT NULL,
 `endat` DATETIME NOT NULL,
 `entries` INT UNSIGNED NOT NULL,
 `exits` INT UNSIGNED NOT NULL,
 `source` ENUM('Counter','Manual') NOT NULL,
 `notes` VARCHAR(255) NULL,
 `revno` INT UNSIGNED NOT NULL DEFAULT 1,
 PRIMARY KEY (`stncode`,`startat`),
 FOREIGN KEY (`stncode`) REFERENCES `station`(`stncode`)
   ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

CREATE TABLE `servicetask` (
 `taskno` VARCHAR(16) NOT NULL PRIMARY KEY,
 `trainno` VARCHAR(12) NOT NULL,
 `taskdate` DATE NOT NULL,
 `tasktype` ENUM('Inspection','Maintenance','Recovery') NOT NULL,
 `hours` DECIMAL(8,2) NOT NULL,
 `details` VARCHAR(255) NOT NULL,
 `revno` INT UNSIGNED NOT NULL DEFAULT 1,
 FOREIGN KEY (`trainno`) REFERENCES `train`(`trainno`)
   ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB;

-- REQUIRED AUTHORITATIVE APPLICATION VALIDATION:
-- Required text is meaningful/nonblank; active is 0/1; revno>=1.
-- One current barangay name per code; preserve repeated descriptions consistently.
-- An operational station needs one Northbound and one Southbound platform. UNIQUE
-- prevents duplicates, not a missing pair. Create inactive, establish both, then
-- activate. Platform capacity>0; platform identity/station/direction protected.
-- Passenger trains require cars>0/paxcap>0 and Service fields NULL. Service
-- trains require dutytype/nonnegative loadton and Passenger fields NULL.
-- Service tasks require an eligible Service train, actual date and hours>0.
-- New ordinary events require appropriate active registers. Historical corrections
-- and departure completion after inactivation need controlled authorization.
-- Arrived calls have depat NULL; Departed requires depat>=arrat. No future actual
-- dates. Train cannot have two unfinished calls or conflicting occupied periods;
-- platform cannot have overlapping occupied call intervals under the case model.
-- Coordinate locks for train/platform, recheck revisions and save arrival/departure
-- state changes atomically. Do not silently move an event to another platform.
-- Gate start aligns to a quarter hour; end=start+15 minutes exclusive. Require
-- end<=authoritative current time, entries/exits>=0, no interval overlap.
-- Same station/start is one consolidated record regardless of source. Correct
-- it rather than adding another source record. Missing does not mean zero.
-- Keep identifiers/history; protect dependent deletion and confirm allowed
-- erroneous-record removal. No unrestricted deletion of real operational history.
-- Compare loaded revno, increment after successful save, reject stale overwrites.
-- Authorization is external; no account or audit-history table is assumed.
-- The omitted row/cross-table rules are NOT guaranteed by this DDL.
-- Reports: all current saved states/register values, not historical reconstruction.
-- R1/R2 retain zero-activity registers. R3 groups calls by actual-arrival period
-- and current state, showing current registered capacity only. R4 sums actual
-- saved intervals, not assumed complete periods. Never join independent tasks
-- or gate counts into train-call aggregates and multiply records.

START TRANSACTION;

-- station: 5 simulated records.

-- platform: 10 simulated records.

-- train: 17 simulated records.

-- traincall: 162996 simulated records.

-- gateflow: 96286 simulated records.

-- servicetask: 173 simulated records.

COMMIT;

