-- -----------------------------------------------------
-- Data Migration
-- -----------------------------------------------------

USE `G09_lrtops`;

-- Disable foreign key checks during batch ETL
SET FOREIGN_KEY_CHECKS = 0;

-- -----------------------------------------------------
-- 1. Populate Reference Lookup Tables
-- -----------------------------------------------------

-- Generate refbarangay records by extracting distinct barangay names from the old station table
SELECT DISTINCT
    brgycode,
    brgyname,
    1
FROM `G09_lrtops_old`.`station`
WHERE brgycode IS NOT NULL
AND brgyname IS NOT NULL;

-- Populate reftasktype reference defaults

-- Migrate refsource lookup records (if existing in old database)


-- -----------------------------------------------------
-- 2. Migrate Station & Platform Data
-- -----------------------------------------------------

-- Map station data using foreign keys to refbarangay
SELECT 
    s.stncode,
    s.stnname,
    s.brgycode,
    s.address,
    s.active,
    s.revno
FROM `G09_lrtops_old`.`station` s
JOIN `refbarangay` b ON s.brgyname = b.brgyname;

-- Migrate platforms
SELECT `platno`, `stncode`, `platname`, `directn`, `capacity`, `active`, `revno`
FROM `G09_lrtops_old`.`platform`
WHERE `platno` IS NOT NULL;


-- -----------------------------------------------------
-- 3. Migrate Train Supertype & Subtypes
-- -----------------------------------------------------

-- Base Train Supertype (stores ONLY clean base attributes: trainno, label, traintyp, active, revno)
SELECT `trainno`, `label`, `traintyp`, `active`, `revno`
FROM `G09_lrtops_old`.`train`;

-- Passenger Train Subtype (extracts cars and paxcap from old train table)
SELECT `trainno`, `cars`, `paxcap`, `revno`
FROM `G09_lrtops_old`.`train`
WHERE `traintyp` = 'Passenger';

-- Service Train Subtype (extracts dutytype and loadton from old train table)
SELECT `trainno`, `dutytype`, `loadton`, `revno`
FROM `G09_lrtops_old`.`train`
WHERE `traintyp` = 'Service';


-- -----------------------------------------------------
-- 4. Migrate Operational Logs & Tasks
-- -----------------------------------------------------

-- Migrate Train Calls
SELECT `callno`, `trainno`, `platno`, `arrat`, `depat`, `status`, `remarks`, `revno`
FROM `G09_lrtops_old`.`traincall`;

-- Migrate Gateflow logs (if populated in old database)
SELECT `stncode`, `startat`, `endat`, `entries`, `exits`, `source`, `notes`, `revno`
FROM `G09_lrtops_old`.`gateflow`;

-- Migrate Service Tasks (if populated in old database)
SELECT `taskno`, `trainno`, `taskdate`, `tasktype`, `hours`, `details`, `revno`
FROM `G09_lrtops_old`.`servicetask`;

-- Re-enable foreign key checks
SET FOREIGN_KEY_CHECKS = 1;
